INSERT INTO cards (id, deck_id, korean, romanisation, translation, notes, position) VALUES
    ('00000000-0000-0000-0003-000000000001', '00000000-0000-0000-0002-000000000001', '안녕하세요',      'annyeonghaseyo',      'Hello / Hi',                       'formal/polite',                         1),
    ('00000000-0000-0000-0003-000000000002', '00000000-0000-0000-0002-000000000001', '감사합니다',      'gamsahamnida',        'Thank you',                        'very formal; 고마워 is casual',         2),
    ('00000000-0000-0000-0003-000000000003', '00000000-0000-0000-0002-000000000001', '죄송합니다',      'joesonghamnida',      'I''m sorry / Excuse me',           'more formal than 미안해요',             3),
    ('00000000-0000-0000-0003-000000000004', '00000000-0000-0000-0002-000000000001', '안녕히 가세요',   'annyeonghi gaseyo',   'Goodbye (to person leaving)',       'you stay, they go',                     4),
    ('00000000-0000-0000-0003-000000000005', '00000000-0000-0000-0002-000000000001', '안녕히 계세요',   'annyeonghi gyeseyo',  'Goodbye (to person staying)',       'you go, they stay',                     5),
    ('00000000-0000-0000-0003-000000000006', '00000000-0000-0000-0002-000000000001', '네',             'ne',                  'Yes',                              '',                                      6),
    ('00000000-0000-0000-0003-000000000007', '00000000-0000-0000-0002-000000000001', '아니요',          'aniyo',               'No',                               'polite; 아니 is casual',                7),
    ('00000000-0000-0000-0003-000000000008', '00000000-0000-0000-0002-000000000001', '괜찮아요',        'gwaenchanayo',        'It''s okay / Are you okay?',        'very versatile phrase',                 8),
    ('00000000-0000-0000-0003-000000000009', '00000000-0000-0000-0002-000000000001', '얼마예요?',       'eolmayeyo',           'How much is it?',                  '',                                      9),
    ('00000000-0000-0000-0003-000000000010', '00000000-0000-0000-0002-000000000001', '이름이 뭐예요?',  'ireumi mwoyeyo',      'What is your name?',               '',                                     10)
