-- ── 2. Password hashes (pgcrypto) ─────────────────────────────────────────────
-- Requires pgcrypto extension (enabled by default in Supabase).
-- Learner accounts keep "ppyong" as password; your account you'll auth via Google
-- or can set any password by changing the value below.
UPDATE users
SET password_hash = crypt('ppyong', gen_salt('bf', 10))
WHERE password_hash = '';

